html:
{#
	====================  CONFIG - TUNE THESE  ====================
	rows_per_page : how many item rows fit in the items table (105mm tbody).
	                 Raise it if pages end early, lower it if rows overlap the footer.

	CSS lives in style.css - in Frappe paste it into the Print Format's
	"Custom CSS" field. Logos must be uploaded to site /files/.
	===============================================================
#}
{%- set rows_per_page = 10 -%}

{%- set items = doc.items or [] -%}
{%- set item_count = items|length -%}
{%- set total_pages = [((item_count - 1) // rows_per_page) + 1, 1]|max -%}

{%- set g = namespace(sr=0) -%}
{%- set cum = namespace(box=0.0, pcs=0.0, ltr=0.0, taxable=0.0, cgst=0.0, sgst=0.0, net=0.0) -%}

{%- set chg = namespace(freight=0.0, discount=0.0, tax_rate=0.0) -%}
{%- for t in doc.taxes or [] -%}
	{%- set desc = ((t.account_head or '') ~ ' ' ~ (t.description or ''))|lower -%}
	{%- if 'gst' in desc -%}{%- set chg.tax_rate = chg.tax_rate + (t.rate|float) -%}{%- endif -%}
	{%- if 'freight' in desc -%}{%- set chg.freight = chg.freight + (t.tax_amount|float) -%}{%- endif -%}
	{%- if 'discount' in desc -%}{%- set chg.discount = chg.discount + (t.tax_amount|float) -%}{%- endif -%}
{%- endfor -%}
{# Bill-level tax totals straight from the doc's tax rows (Refund excluded).
   Freight Actual rows never match cgst/sgst/igst names. #}
{%- set dtax = namespace(cgst=0.0, sgst=0.0, igst=0.0, c_rate=0.0, s_rate=0.0) -%}
{%- for t in doc.taxes or [] -%}
{%- set ah = (t.account_head or '')|lower -%}
{%- if 'refund' not in ah -%}
{%- if 'cgst' in ah -%}{%- set dtax.cgst = dtax.cgst + (t.tax_amount|float) -%}{%- if not dtax.c_rate -%}{%- set dtax.c_rate = (t.rate|float) -%}{%- endif -%}{%- endif -%}
{%- if 'sgst' in ah -%}{%- set dtax.sgst = dtax.sgst + (t.tax_amount|float) -%}{%- if not dtax.s_rate -%}{%- set dtax.s_rate = (t.rate|float) -%}{%- endif -%}{%- endif -%}
{%- if 'igst' in ah -%}{%- set dtax.igst = dtax.igst + (t.tax_amount|float) -%}{%- endif -%}
{%- endif -%}
{%- endfor -%}
{# Original bill subtotal (rate x qty as entered, pre-discount). #}
{%- set sub_total = (doc.items|sum(attribute='amount'))|float -%}
{%- set round_off = doc.rounding_adjustment|float -%}
{%- set rounded_total = doc.rounded_total|float -%}

{%- set caddr = frappe.db.get_value('Address', doc.company_address,
	['address_line1', 'address_line2', 'city', 'state', 'pincode', 'phone', 'gstin'],
	as_dict=True) if doc.company_address else '' -%}
{%- set c_line1 = '5 SHIV INDUSTRY, OPP. THAKOR DWAR FARM,' -%}
{%- set c_line2 = 'LASKANA, SURAT, GUJARAT - 394185 +91 90224 13151' -%}
{%- if caddr -%}
	{%- set parts = [] -%}
	{%- if caddr.address_line1 -%}{%- set _ = parts.append(caddr.address_line1) -%}{%- endif -%}
	{%- if caddr.address_line2 -%}{%- set _ = parts.append(caddr.address_line2) -%}{%- endif -%}
	{#{%- if parts -%}{%- set c_line1 = parts|join(', ') -%}{%- endif -%}#}
	{%- set tail = [] -%}
	{%- if caddr.city -%}{%- set _ = tail.append(caddr.city) -%}{%- endif -%}
	{%- if caddr.state -%}{%- set _ = tail.append(caddr.state) -%}{%- endif -%}
	{%- if caddr.pincode -%}{%- set _ = tail.append('- ' ~ caddr.pincode) -%}{%- endif -%}
	{%- if caddr.phone -%}{%- set _ = tail.append(caddr.phone) -%}{%- endif -%}
	{#{%- if tail -%}{%- set c_line2 = tail|join(' ') -%}{%- endif -%}#}
{%- endif -%}

{%- macro m2(v) -%}{{ "%.2f"|format(v|float) }}{%- endmacro -%}
{%- macro m3(v) -%}{{ "%.3f"|format(v|float) }}{%- endmacro -%}
{%- macro sgn(v) -%}
	{%- set v = v|float -%}
	{%- if v < 0 -%}- {{ "%.2f"|format(-v) }}{%- else -%}{{ "%.2f"|format(v) }}{%- endif -%}
{%- endmacro -%}

{%- for page in range(total_pages) -%}
	{%- set start = page * rows_per_page -%}
	{%- set end = [start + rows_per_page, item_count]|min -%}
	{%- set page_items = items[start:end] -%}
	{%- set is_last = page == total_pages - 1 -%}
	{%- set ps = namespace(box=0.0, pcs=0.0, ltr=0.0, taxable=0.0, cgst=0.0, sgst=0.0, net=0.0) -%}

	{%- set b_name = doc.customer_name or doc.customer or '' -%}
	{#{%- set b_place = doc.place_of_supply or '' -%}#}
	{%- set c_addr_data = frappe.db.get_value('Address', doc.customer_address, ['gst_state', 'gst_state_number'], as_dict=True) if doc.customer_address else None -%}
    {%- set b_place = (c_addr_data.gst_state_number ~ '-' ~ c_addr_data.gst_state) if (c_addr_data and c_addr_data.gst_state and c_addr_data.gst_state_number) else (doc.place_of_supply or '') -%}
	{%- set b_gstin = doc.billing_address_gstin or '' -%}
	{%- set s_gstin = doc.shipping_address_gstin or b_gstin -%}
	{%- set b_city = frappe.db.get_value('Address', doc.customer_address, 'city') if doc.customer_address else '' -%}
    {%- set s_city = frappe.db.get_value('Address', doc.shipping_address_name, 'city') if doc.shipping_address_name else b_city -%}
	{#{%- set phone = doc.contact_phone or doc.phone or '' -%}#}
	{%- set phone = (frappe.db.get_value('Contact', doc.contact_person, 'phone') or frappe.db.get_value('Contact', doc.contact_person, 'mobile_no')) if doc.contact_person else '' -%}
{%- if not phone -%}{%- set phone = doc.contact_phone or doc.phone or doc.contact_mobile or '' -%}{%- endif -%}
{%- if not phone -%}{%- set _pcust = doc.get('customer') or doc.get('party_name') or '' -%}{%- if _pcust -%}{%- set phone = frappe.db.get_value('Customer', _pcust, 'mobile_no') or '' -%}{%- endif -%}{%- endif -%}

	{%- set buyer_raw = (doc.address_display or '').replace('<br/>','\n').replace('<br>','\n').replace('<BR>','\n').split('\n') -%}
	{%- set buyer_arr = [] -%}
	{%- for l in buyer_raw -%}{%- if l|trim -%}{%- set _ = buyer_arr.append(l|trim) -%}{%- endif -%}{%- endfor -%}
	{%- set ship_raw = (doc.shipping_address or doc.address_display or '').replace('<br/>','\n').replace('<br>','\n').replace('<BR>','\n').split('\n') -%}
	{%- set ship_arr = [] -%}
	{%- for l in ship_raw -%}{%- if l|trim -%}{%- set _ = ship_arr.append(l|trim) -%}{%- endif -%}{%- endfor -%}

	{%- set eway = doc.get('ewaybill') or doc.get('eway_bill_no') or '' -%}
	{%- set po = doc.po_no or '' -%}
	
	{%- set irn = doc.get('irn') or '' -%}
    {%- set irn1 = irn[:32] if irn else '' -%}
    {%- set irn2 = irn[32:64] if irn|length > 32 else '' -%}
    {%- set ack_no = doc.get('ack_no') or '' -%}
    {%- set ack_date = doc.get('ack_date') or '' -%}
    {%- set qr = doc.get('qr_code') or doc.get('einvoice_qr') or doc.get('e_invoice_qr') or '' -%}
    {%- if irn and (not ack_no or not qr) -%}
        {%- set eil = frappe.db.get_value('e-Invoice Log', irn, ['acknowledgement_number', 'acknowledged_on', 'signed_qr_code'], as_dict=True, ignore=True) -%}
        {%- if eil -%}
            {%- set ack_no = ack_no or eil.acknowledgement_number -%}
            {%- set ack_date = ack_date or eil.acknowledged_on -%}
            {%- if not qr and eil.signed_qr_code -%}{%- set qr = 'data:image/png;base64,' ~ get_qr_code(eil.signed_qr_code) -%}{%- endif -%}
        {%- endif -%}
    {%- endif -%}
    
	{%- set vlines = [] -%}
	{%- for line in (doc.get('vehicle_details') or doc.get('vehicle_no') or '').replace('<br>','\n').split('\n') -%}
		{%- if line|trim -%}{%- set _ = vlines.append(line|trim) -%}{%- endif -%}
	{%- endfor -%}
	{%- set vhalf = ((vlines|length) + 1)//2 -%}
	
	
	
	{# Fetch Address fields directly from the database #}
	{%- set b_addr_data = frappe.db.get_value('Address', doc.customer_address, ['address_line1', 'address_line2', 'city'], as_dict=True) if doc.customer_address else {} -%}
	{%- set b_addr_line1 = (b_addr_data.get('address_line1') or '')|truncate(42, true, '...', 0) -%}
	{%- set b_addr_line2 = b_addr_data.get('address_line2') or '' -%}
	{%- set b_city = b_addr_data.get('city') or '' -%}
	
	{# Split Buyer Address Line 1 by the manual newline #}
	{%- set b_line1_parts = b_addr_line1.replace('\r\n', '\n').split('\n') -%}
	{%- set buyer_line_1 = b_line1_parts[0] if b_line1_parts|length > 0 else '' -%}
	{%- set buyer_line_2 = b_line1_parts[1] if b_line1_parts|length > 1 else '' -%}
	{%- set buyer_line_3 = b_city -%}

	{# Fetch and split Ship To Address #}
	{%- set s_addr_data = frappe.db.get_value('Address', doc.shipping_address_name, ['address_line1', 'address_line2', 'city'], as_dict=True) if doc.shipping_address_name else b_addr_data -%}
	{%- set s_addr_line1 = (s_addr_data.get('address_line1') or '')|truncate(42, true, '...', 0) -%}
	{%- set s_addr_line2 = s_addr_data.get('address_line2') or '' -%}
	{%- set s_city = s_addr_data.get('city') or '' -%}

	{%- set s_line1_parts = s_addr_line1.replace('\r\n', '\n').split('\n') -%}
	{%- set ship_line_1 = s_line1_parts[0] if s_line1_parts|length > 0 else '' -%}
	{%- set ship_line_2 = s_line1_parts[1] if s_line1_parts|length > 1 else '' -%}
	{%- set ship_line_3 = s_city -%}

	<div class="sheet{% if is_last %} is-last{% endif %}">
		<div class="frame">

			<!-- ===================== HEADER ===================== -->
			<div class="topbar">

				<div class="logos">
					<div><img src="/files/servo-logo.jpg" alt="logo"></div>
					<div>
						<img src="/files/Geeta Corpo logo.jpg" alt="logo">
						<div class="address-gstin">
							<div class="address">
								<span>{{ c_line1 }}</span>
								<span>{{ c_line2 }}</span>
							</div>
							<div>
							    {%- set company_gstin = frappe.db.get_value('Company', doc.company, 'gstin') -%}
								<p class="gst">GSTIN No.: {{ company_gstin }}</p>
							</div>
						</div>
					</div>
					<div><img src="/files/IndianOilLogo1024x768.jpg" alt="logo"></div>
				</div>

				<div class="title">
					<div><p class="debitnote">Debit Memo</p></div>
					<div><p class="taxinvoice">TAX INVOICE</p></div>
					<div><p class="original">Original</p></div>
				</div>

				<div class="labels">
					<div><span>Buyer To Party</span></div>
					<div><span>Ship To Party</span></div>
				</div>

				<div class="party">
					<div class="buyer">
						<div><b><span>M/s. <span>:</span></span></b></div>
						<div><span>&nbsp;</span></div>
						<div><span>&nbsp;</span></div>
						<div><span>&nbsp;</span></div>
						<div><b><span>Place of Supply <span>:</span></span></b></div>
						<div><b><span>GSTIN No. <span>:</span></span></b></div>
						<div><b><span>Phone <span>:</span></span></b></div>
					</div>
					<div class="buyervalues">
						<div><b><span>{{ b_name }}</span></b></div>
						<div><span>{{ b_addr_line1 or '&nbsp;'}}</span></div>
						<div><span>{{ b_addr_line2 or '&nbsp;' }}</span></div>
						<div><b><span>{{ buyer_line_3 or '&nbsp;'}}</span></b></div>
						<div><span>{{ b_place or '&nbsp;'}}</span></div>
						<div><span>{{ b_gstin or '&nbsp;' }}</span></div>
						<div><span>{{ phone or '&nbsp;' }}</span></div>
					</div>
					<div class="ship">
						<div><b><span>M/s. <span>:</span></span></b></div>
						<div><span>&nbsp;</span></div>
						<div><span>&nbsp;</span></div>
						<div><span>&nbsp;</span></div>
						<div><b><span>Place of Supply <span>:</span></span></b></div>
						<div><b><span>GSTIN No. <span>:</span></span></b></div>
						<div><b><span>Phone <span>:</span></span></b></div>
					</div>
					<div class="shipvalues">
						<div><b><span>{{ b_name }}</span></b></div>
						<div><span>{{ s_addr_line1 or '&nbsp;' }}</span></div>
						<div><span>{{ s_addr_line2 or '&nbsp;' }}</span></div>
						<div><b><span>{{ ship_line_3 or '&nbsp;' }}</span></b></div>
						<div><span>{{ b_place or '&nbsp;' }}</span></div>
						<div><span>{{ s_gstin or '&nbsp;' }}</span></div>
						<div><span>{{ phone or '&nbsp;' }}</span></div>
					</div>
				</div>

				<div class="info">
					<div class="left">
						<div class="heads">
							<span>Time <span>:</span></span>
							<span>SSF <span>:</span></span>
							<span>E-way bill No. <span>:</span></span>
						</div>
						<div>
							<span>{{ frappe.utils.format_time(doc.creation) if doc.creation else '' }}</span>
							<span>{{ doc.get('ssf') or '' }}</span>
							<span>{{ eway }}</span>
						</div>
					</div>
					<div class="right">
						<div class="heads">
							<span>Invoice No. <span>:</span></span>
							<span>Date <span>:</span></span>
							<span>Po No <span>:</span></span>
						</div>
						<div>
							<span>{{ doc.name }}</span>
							<span>{{ doc.get_formatted('posting_date') }}</span>
							<span>{{ po }}</span>
						</div>
					</div>
				</div>
			</div>

			<!-- ===================== ITEMS TABLE ===================== -->
			<div class="items-wrap">
				<table class="items">
					<colgroup>
						<col width="3%">
						<col width="27%">
						<col width="7%">
						<col width="6%">
						<col width="7%">
						<col width="7%">
						<col width="7%">
						<col width="8%">
						<col width="5%">
						<col width="7%">
						<col width="7%">
						<col width="9%">
					</colgroup>
					<thead>
						<tr>
							<th rowspan="2">Sr.</th>
							<th rowspan="2">Product Name</th>
							<th rowspan="2">HSN/SAC Code</th>
							<th rowspan="2">Box</th>
							<th rowspan="2">Pcs</th>
							<th rowspan="2">Ltr</th>
							<th rowspan="2">Rate</th>
							<th rowspan="2">Taxable Amount</th>
							<th rowspan="2">GST %</th>
							<th colspan="2">Tax Amount</th>
							<th rowspan="2">Net Amount</th>
						</tr>
						<tr>
							<th>Central</th>
							<th>State/UT</th>
						</tr>
					</thead>
					<tbody>
						{%- for row in page_items -%}
                        	{%- set g.sr = g.sr + 1 -%}
                        	{# BILL-LEVEL presentation: row shows original rate x qty.
                         	   Tax cells are proportional shares of the doc's CGST/SGST
                         	   totals, so columns sum exactly to the bill values. #}
                        	{%- set taxable = (row.amount or 0)|float -%}
                        	{%- set share = (taxable / sub_total) if sub_total else 0 -%}
                        	{%- set ct = dtax.cgst * share -%}
                        	{%- set st = dtax.sgst * share -%}
                        	{%- set item_gst_rate = (row.get('cgst_rate') or 0)|float + (row.get('sgst_rate') or 0)|float -%}
                        	{%- set item_gst_rate = item_gst_rate or (dtax.c_rate + dtax.s_rate) -%}
                        	{%- set net = taxable + ct + st -%}
                        	{%- set box = (row.fe_box or 0)|float -%}
                        	{%- set pcs = (row.pcs_qty or row.pcs or row.qty or 0)|float -%}
                        	{%- set ltr = (row.fe_ltr or row.ltr_qty or row.ltr or 0)|float -%}
                        	
                        	{%- set ps.box = ps.box + box -%}
                        	{%- set ps.pcs = ps.pcs + pcs -%}
                        	{%- set ps.ltr = ps.ltr + ltr -%}
                        	{%- set ps.taxable = ps.taxable + taxable -%}
                        	{%- set ps.cgst = ps.cgst + ct -%}
                        	{%- set ps.sgst = ps.sgst + st -%}
                        	{%- set ps.net = ps.net + net -%}
                        	<tr>
                        		<td>{{ g.sr }}</td>
                        		{#<td class="i-name">{{ row.item_name or row.item_code or row.description or '' }}<div class="sub">MRP:-{% if row.get('mrp') %} {{ m2(row.mrp) }}{% endif %}</div></td>#}
                        		<td>{% set iname = row.item_name or row.item_code or row.description or '' %}{% if '-MRP-' in iname %}{{ iname.split('-MRP-')[0]|trim }}{% else %}{{ iname }}{% endif %}<div class="sub">MRP:-{% if row.get('mrp') %} {{ m2(row.mrp) }}{% endif %}</div></td>
                        		<td>{{ row.gst_hsn_code or row.hsn_sac or '' }}</td>
                        		<td>{{ m2(box) }}</td>
                        		<td>{{ m2(pcs) }}</td>
                        		<td>{{ m3(ltr) }}</td>
                        		<td>{{ m2(row.rate) }}</td>
                        		<td>{{ m2(taxable) }}</td>
                        		
                        		{# Printing the dynamic system rate instead of hardcoded 18% #}
                        		<td>{{ m2(item_gst_rate) }}%</td>
                        		
                        		<td>{{ m2(ct) }}</td>
                        		<td>{{ m2(st) }}</td>
                        		<td>{{ m2(net) }}</td>
                        	</tr>
                        {%- endfor -%}
						{%- if page_items|length < rows_per_page -%}
							<tr class="fill">
								<td></td><td></td><td></td><td></td><td></td><td></td>
								<td></td><td></td><td></td><td></td><td></td><td></td>
							</tr>
						{%- endif -%}
					</tbody>
					<tfoot>
						<tr>
							<td></td>
							<td></td>
							<td>Total</td>
							<td>{{ m2(cum.box + ps.box) }}</td>
							<td>{{ m2(cum.pcs + ps.pcs) }}</td>
							<td>{{ m3(cum.ltr + ps.ltr) }}</td>
							<td></td>
							<td>{{ m2(cum.taxable + ps.taxable) }}</td>
							<td></td>
							<td>{{ m2(cum.cgst + ps.cgst) }}</td>
							<td>{{ m2(cum.sgst + ps.sgst) }}</td>
							<td>{{ m2(cum.net + ps.net) }}</td>
						</tr>
					</tfoot>
				</table>
			</div>

			<!-- ===================== FOOTER ===================== -->
			<div class="footer">
				<div class="bandt">
					<div class="bankandtransport">
						<div class="bankandtrans">
							<div class="bankandvalues">
								<div class="bank">
									<div><b><span>Bank Name</span><span>:</span></b></div>
									<div><b><span>Bank A/c. No.</span><span>:</span></b></div>
									<div><b><span>RTGS/IFSC Code </span><span> : </span></b></div>
								</div>
								<div class="bankvalues">
									<div><span>{{ doc.get('bank_name') or 'IDFC FIRST BANK' }}</span></div>
									<div><span>{{ doc.get('bank_account_no') or '69909094123' }}</span></div>
									<div><span>{{ doc.get('ifsc_code') or 'IDFB0042267' }}</span></div>
								</div>
							</div>
						</div>
						<div class="invoiceandvehicle">
							<div class="ackandvehicle">
								<div class="einvoice">
									<div class="irnandack">
										<div class="irnandacklabel">
											<div><b><span>IRN No</span><span>:</span></b></div>
											<div><b>&nbsp;</b></div>
											<div><b><span>Ack No</span><span>:</span></b></div>
											<div><b><span>Ack Date</span><span> : </span></b></div>
										</div>
										
										   <div class="irnandackvalues">
                                            <div><span>{{ irn1 or '&nbsp;' }}</span></div>
                                            <div><span>{{ irn2 or '&nbsp;' }}</span></div>
                                            <div><span>{{ ack_no or '&nbsp;' }}</span></div>
                                            <div><span>{{ frappe.utils.format_datetime(ack_date, 'dd/MM/yyyy hh:mm:ss') if ack_date else '&nbsp;' }}</span></div>
                                        </div>
									</div>
								</div>

								<div class="vehicle">
                                    <div class="line"><b><span>Vehicle Details</span><span>:</span></b></div>
                                    <div class="vehicles">
                                        <div class="line-clamp-1">
                                            <div>
                                                <span class="box"></span>
                                                <span>1. GJ05BX9053</span>
                                            </div>
                                            <div>
                                                <span class="box"></span>
                                                <span>2. GJ05BZ9976</span>
                                            </div>
                                            <div>
                                                <span class="box"></span>
                                                <span>3. GJ05CU2271</span>
                                            </div>
                                        </div>
                                        <div class="line-clamp-1">
                                            <div>
                                                <span class="box"></span>
                                                <span>4. GJ05CW4572</span>
                                            </div>
                                            <div>
                                                <span class="box"></span>
                                                <span>5. Transport</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>
							</div>
							<div class="qr">
								<div class="e-invoice-label-qr">
									<div class="e-invoice-lable">
										<div><span>E-Invoice</span></div>
									</div>
									<div class="e-invoice-qr">
										<div class="qr-box">{% if qr %}<img src="{{ qr }}" alt="QR">{% else %}&nbsp;{% endif %}</div>
									</div>
								</div>
							</div>
						</div>
						<div class="billinword">
							<div style="height:7.5mm">
								{% if is_last %}
								<span><b>Bill Amount :</b></span>
								<span><i>{{ frappe.utils.money_in_words(doc.rounded_total) }}</i></span>
								{% endif %}
							</div>
						</div>
					</div>

					<div class="totalandnote">
						{% if not is_last %}
						<div class="cf">
							<div><b><span>C/F to Next Page</span></b></div>
							<div><span>{{ m2(cum.net + ps.net) }}</span></div>
						</div>
						{% endif %}
						<div class="closing">
							<div><b><span>Closing Bal.:</span></b></div>
							<div><span>{{ m2(cum.net + ps.net) }}</span></div>
						</div>
						<div class="roundoff">
							<div><span>Sub Total :</span></div>
							<div><span>{{ m2(cum.taxable + ps.taxable) }}</span></div>
						</div>
<div class="roundoff">
							<div><span>Taxable Value :</span></div>
							<div><span>{{ m2(doc.net_total) }}</span></div>
						</div>
<div class="tax">
							<div><span>Tax : </span><span>{{ "%.2f"|format(chg.tax_rate) }}%</span></div>
							<div><span>{{ m2(cum.cgst + ps.cgst + cum.sgst + ps.sgst) }}</span></div>
						</div>
						<div class="roundoff">
							<div><span>Round off :</span></div>
							<div><span>{{ sgn(round_off) }}</span></div>
						</div>
						<div class="roundoff">
							<div><span>Freight :</span></div>
							<div><span>{{ sgn(chg.freight) }}</span></div>
						</div>
						<div class="roundoff">
							<div><span>Discount :</span></div>
							{#<div><span>{{ sgn(chg.discount) }}</span></div>#}
							<div><span>{{ sgn(doc.discount_amount) }}</span></div>
						</div>
						{% if is_last %}
						<div class="gt">
							<div><b><span>Grand Total</span></b></div>
							<div><b><span>{{ m2(rounded_total) }}</span></b></div>
						</div>
						{% endif %}
						<div class="note">
							<div><b><span>Note :</span></b></div>
						</div>
					</div>
				</div>

				<div class="tandcandsign">
					<div class="tandc">
						<b>Terms &amp; Condition :</b>
						<ol class="terms">
							{% if doc.terms %}
							{% for line in doc.terms.replace('<br>','\n').replace('<br/>','\n').split('\n') %}
							{% if line|trim %}<li>{{ line|trim|safe }}</li>{% endif %}
							{% endfor %}
							{% else %}
							<li>Goods once sold will not be taken back.</li>
							<li>Interest @18% p.a. will be charged if payment is not made within due date.</li>
							<li>Our risk and responsibility ceases as soon as the goods leave our premises.</li>
							<li>Cheque Bounce Charges Rs.500 + GST Compulsory</li>
							<li>"Subject to 'SURAT' Jurisdiction only. &nbsp;E.&amp;O.E"</li>
							{% endif %}
						</ol>
					</div>
					<div class="sign">
						<div><b>For, {{ doc.company }}</b></div>
						<div class="mvandas">
							<div class="mv"><b>Material Verify By</b></div>
							<div class="as">(Authorised Signatory)</div>
						</div>
					</div>
				</div>
			</div>

		</div>
	</div>

	{%- set cum.box = cum.box + ps.box -%}
	{%- set cum.pcs = cum.pcs + ps.pcs -%}
	{%- set cum.ltr = cum.ltr + ps.ltr -%}
	{%- set cum.taxable = cum.taxable + ps.taxable -%}
	{%- set cum.cgst = cum.cgst + ps.cgst -%}
	{%- set cum.sgst = cum.sgst + ps.sgst -%}
	{%- set cum.net = cum.net + ps.net -%}
{%- endfor -%}

