html:
{#
	====================  CONFIG - TUNE THESE  ====================
	rows_per_page : how many item rows fit in the items table (105mm tbody).
	                 Raise it if pages end early, lower it if rows overlap the footer.

	CSS lives in style.css - in Frappe paste it into the Print Format's
	"Custom CSS" field. Logos must be uploaded to site /files/.
	===============================================================
#}
{%- set rows_per_page = 10 -%}

{%- set items = doc.items or [] -%}
{%- set item_count = items|length -%}
{%- set total_pages = [((item_count - 1) // rows_per_page) + 1, 1]|max -%}

{%- set g = namespace(sr=0) -%}
{%- set cum = namespace(box=0.0, pcs=0.0, ltr=0.0, taxable=0.0, cgst=0.0, sgst=0.0, igst=0.0, net=0.0) -%}

{%- set chg = namespace(freight=0.0, discount=0.0, tax_rate=0.0) -%}

{%- set tax_check = namespace(is_igst=false) -%}
{%- for t in doc.taxes or [] -%}
    {%- if 'igst' in (t.account_head or '')|lower -%}
        {%- set tax_check.is_igst = true -%}
    {%- endif -%}
{%- endfor -%}
{%- set is_igst = tax_check.is_igst -%}

