{%- set cum.ltr = cum.ltr + ps.ltr -%}
{%- set cum.taxable = cum.taxable + ps.taxable -%}
{%- set cum.cgst = cum.cgst + ps.cgst -%}
{%- set cum.sgst = cum.sgst + ps.sgst -%}
{%- set cum.igst = cum.igst + ps.igst -%}
{%- set cum.net = cum.net + ps.net -%}


{% endfor %}

