@media print {

    /* body { background: #fff; } */
    .sheet {
        width: auto;
        height: 296mm;
        margin: 0;
        padding: 8mm;
        box-shadow: none;
        page-break-after: always;
    }

    .sheet.is-last {
        page-break-after: auto;
    }

    * {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
}

html:
{#
CREDIT NOTE WITH STOCK - Dynamic multi-page print format (Sales Invoice / Sales Return).
Paste the contents of style.css into the Print Format's "Custom CSS" field.
Tune rows_per_page so that body rows (plus thead/tfoot) fit the 105mm items-wrap.
#}
{% set rows_per_page = 13 %}
{% set items = doc.items or [] %}
{% set item_count = items | length %}
{% set total_pages = (item_count / rows_per_page) | round(0, 'ceil') | int %}
{% if total_pages == 0 %}{% set total_pages = 1 %}{% endif %}

{% macro m1(v) %}{{ '%.1f' | format((v or 0) | float | abs) }}{% endmacro %}
{% macro m2(v) %}{{ '%.2f' | format((v or 0) | float | abs) }}{% endmacro %}
{% macro m3(v) %}{{ "%.3f"|format(v|float) }}{% endmacro %}
{% macro mcm(v) %}{{ ('{:,.2f}').format((v or 0) | float | abs) }}{% endmacro %}
{% macro sgn(v) %}{% if (v or 0) | float < 0 %}- {{ '%.2f' | format(v | float | abs) }}{% else %}{{ '%.2f' | format(v | float) }}{% endif %}{% endmacro %}

{% set company_gstin = doc.company_gstin or doc.get('company_gstin') or '' %}

{# company header address: company_address override, else static fallback #}
{% set c_addr = frappe.db.get_value('Address', doc.company_address or '', 'address_line1') %}
{% set c_l1 = c_addr if c_addr else '6,SHIV IND. OPP.J B DIAMOND SCHOOL, LASKANA,SURAT' %}
{% set c_addr2 = frappe.db.get_value('Address', doc.company_address or '', 'address_line2') %}
{% set c_l2 = c_addr2 if c_addr2 else 'Mo. 9022413151 | globalgreenenergy001@gmail.com' %}

{# original bill date (from the invoice being returned) #}
{% set orig_date_val = frappe.db.get_value('Sales Invoice', doc.return_against or '', 'posting_date') %}
{% if not orig_date_val %}{% set orig_date_val = '' %}{% endif %}

{# buyer address display, dedupe blank lines #}
{% set blines = doc.address_display.split('



') if doc.address_display else [] %}
{% set alines = [] %}
{% for bl in blines %}
{% if bl | trim %}{% set _ = alines.append(bl | trim) %}{% endif %}
{% endfor %}

{# trailing rows placeholder (#) #}
{% set rows_data = [] %}
{% for item in doc.items %}
{% set t = (item.net_amount or item.amount or 0) | float | abs %}
{% set g_rate = (item.gst_rate or item.gst_percentage or 0) | float %}
{% set c = (item.get('cgst_amount') if item.get('cgst_amount') != None else t * g_rate / 200) | float | abs %}
{% set s = (item.get('sgst_amount') if item.get('sgst_amount') != None else t * g_rate / 200) | float | abs %}
{% set x = c + s %}
{% set _ = rows_data.append({'q': (item.qty or 0) | float | abs, 'g': g_rate, 't': t, 'c': c, 's': s, 'x': x, 'n': t + x}) %}
{% endfor %}
{% set item_count = rows_data | length %}

{# Global variables moved outside the loop to prevent resetting on page 2 #}
{%- set g = namespace(sr=0) -%}
{%- set cum = namespace(box=0.0, pcs=0.0, ltr=0.0, taxable=0.0, cgst=0.0, sgst=0.0, net=0.0) -%}

{% for page in range(total_pages) %}
{% set start = page * rows_per_page %}
{% set page_rows = rows_data[start:start + rows_per_page] %}
{% set cum_rows = rows_data[:start + rows_per_page] %}
{% set is_last = (page + 1) == total_pages %}

{% set pns = namespace(q=0.0, t=0.0, c=0.0, s=0.0, x=0.0, n=0.0) %}
{% for rd in page_rows %}
    {% set pns.q = pns.q + rd.q %}
    {% set pns.t = pns.t + rd.t %}
    {% set pns.c = pns.c + rd.c %}
    {% set pns.s = pns.s + rd.s %}
    {% set pns.x = pns.x + rd.x %}
    {% set pns.n = pns.n + rd.n %}
{% endfor %}

{% set cns = namespace(q=0.0, t=0.0, c=0.0, s=0.0, x=0.0, n=0.0) %}
{% for rd in cum_rows %}
    {% set cns.q = cns.q + rd.q %}
    {% set cns.t = cns.t + rd.t %}
    {% set cns.c = cns.c + rd.c %}
    {% set cns.s = cns.s + rd.s %}
    {% set cns.x = cns.x + rd.x %}
    {% set cns.n = cns.n + rd.n %}
{% endfor %}
    
{% set total_gst = cns.c + cns.s %}

{% set grand_total = (doc.grand_total or cns.n) | float | abs %}
{% set round_off = (doc.rounding_adjustment or 0) | float %}
{% set total_gst_words = frappe.utils.money_in_words(cns.x) if is_last else '' %}
{% set bill_amount_words = frappe.utils.money_in_words(grand_total) if is_last else '' %}


{#--------------------------------------------------------------#}

{%- set chg = namespace(freight=0.0, discount=0.0, tax_rate=0.0) -%}
{%- for t in doc.taxes or [] -%}
	{%- set desc = ((t.account_head or '') ~ ' ' ~ (t.description or ''))|lower -%}
	{%- if 'gst' in desc -%}{%- set chg.tax_rate = chg.tax_rate + (t.rate|float) -%}{%- endif -%}
	{%- if 'freight' in desc -%}{%- set chg.freight = chg.freight + (t.tax_amount|float) -%}{%- endif -%}
	{%- if 'discount' in desc -%}{%- set chg.discount = chg.discount + (t.tax_amount|float) -%}{%- endif -%}
{%- endfor -%}
{%- set round_off = doc.rounding_adjustment|float -%}
{%- set rounded_total = doc.rounded_total | float | abs -%}
{% set rounded_amount_words = frappe.utils.money_in_words(rounded_total) if is_last else '' %}

{%- set caddr = frappe.db.get_value('Address', doc.company_address,
	['address_line1', 'address_line2', 'city', 'state', 'pincode', 'phone', 'gstin'],
	as_dict=True) if doc.company_address else '' -%}
{%- set c_line1 = '5 SHIV INDUSTRY, OPP. THAKOR DWAR FARM,' -%}
{%- set c_line2 = 'LASKANA, SURAT, GUJARAT - 394185 +91 90224 13151' -%}
{%- if caddr -%}
	{%- set parts = [] -%}
	{%- if caddr.address_line1 -%}{%- set _ = parts.append(caddr.address_line1) -%}{%- endif -%}
	{%- if caddr.address_line2 -%}{%- set _ = parts.append(caddr.address_line2) -%}{%- endif -%}
	{%- set tail = [] -%}
	{%- if caddr.city -%}{%- set _ = tail.append(caddr.city) -%}{%- endif -%}
	{%- if caddr.state -%}{%- set _ = tail.append(caddr.state) -%}{%- endif -%}
	{%- if caddr.pincode -%}{%- set _ = tail.append('- ' ~ caddr.pincode) -%}{%- endif -%}
	{%- if caddr.phone -%}{%- set _ = tail.append(caddr.phone) -%}{%- endif -%}
{%- endif -%}

	{%- set end = [start + rows_per_page, item_count]|min -%}
	{%- set page_items = items[start:end] -%}
	{%- set is_last = page == total_pages - 1 -%}
	{%- set ps = namespace(box=0.0, pcs=0.0, ltr=0.0, taxable=0.0, cgst=0.0, sgst=0.0, net=0.0) -%}

	{%- set b_name = doc.customer_name or doc.customer or '' -%}
	{%- set c_addr_data = frappe.db.get_value('Address', doc.customer_address, ['gst_state', 'gst_state_number'], as_dict=True) if doc.customer_address else None -%}
    {%- set b_place = (c_addr_data.gst_state_number ~ '-' ~ c_addr_data.gst_state) if (c_addr_data and c_addr_data.gst_state and c_addr_data.gst_state_number) else (doc.place_of_supply or '') -%}
	{%- set b_gstin = doc.billing_address_gstin or '' -%}
	{%- set s_gstin = doc.shipping_address_gstin or b_gstin -%}
	{%- set b_city = frappe.db.get_value('Address', doc.customer_address, 'city') if doc.customer_address else '' -%}
    {%- set s_city = frappe.db.get_value('Address', doc.shipping_address_name, 'city') if doc.shipping_address_name else b_city -%}
	{%- set phone = frappe.db.get_value('Contact', doc.contact_person, 'phone') or frappe.db.get_value('Contact', doc.contact_person, 'mobile_no') if doc.contact_person else (doc.contact_phone or doc.phone or '') -%}

	{%- set buyer_raw = (doc.address_display or '').replace('<br/>','\n').replace('<br>','\n').replace('<BR>','\n').split('\n') -%}
	{%- set buyer_arr = [] -%}
	{%- for l in buyer_raw -%}{%- if l|trim -%}{%- set _ = buyer_arr.append(l|trim) -%}{%- endif -%}{%- endfor -%}
	{%- set ship_raw = (doc.shipping_address or doc.address_display or '').replace('<br/>','\n').replace('<br>','\n').replace('<BR>','\n').split('\n') -%}
	{%- set ship_arr = [] -%}
	{%- for l in ship_raw -%}{%- if l|trim -%}{%- set _ = ship_arr.append(l|trim) -%}{%- endif -%}{%- endfor -%}

	{%- set eway = doc.get('ewaybill') or doc.get('eway_bill_no') or '' -%}
	{%- set po = doc.po_no or '' -%}
	
	{%- set irn = doc.get('irn') or '' -%}
    {%- set irn1 = irn[:32] if irn else '' -%}
    {%- set irn2 = irn[32:64] if irn|length > 32 else '' -%}
    {%- set ack_no = doc.get('ack_no') or '' -%}
    {%- set ack_date = doc.get('ack_date') or '' -%}
    {%- set qr = doc.get('qr_code') or doc.get('einvoice_qr') or doc.get('e_invoice_qr') or '' -%}
    {%- if irn and (not ack_no or not qr) -%}
        {%- set eil = frappe.db.get_value('e-Invoice Log', irn, ['acknowledgement_number', 'acknowledged_on', 'signed_qr_code'], as_dict=True, ignore=True) -%}
        {%- if eil -%}
            {%- set ack_no = ack_no or eil.acknowledgement_number -%}
            {%- set ack_date = ack_date or eil.acknowledged_on -%}
            {%- if not qr and eil.signed_qr_code -%}{%- set qr = 'data:image/png;base64,' ~ get_qr_code(eil.signed_qr_code) -%}{%- endif -%}
        {%- endif -%}
    {%- endif -%}
    
	{%- set vlines = [] -%}
	{%- for line in (doc.get('vehicle_details') or doc.get('vehicle_no') or '').replace('<br>','\n').split('\n') -%}
		{%- if line|trim -%}{%- set _ = vlines.append(line|trim) -%}{%- endif -%}
	{%- endfor -%}
	{%- set vhalf = ((vlines|length) + 1)//2 -%}
	
	
	
	{# Fetch Address fields directly from the database #}
	{%- set b_addr_data = frappe.db.get_value('Address', doc.customer_address, ['address_line1', 'address_line2', 'city'], as_dict=True) if doc.customer_address else {} -%}
	{%- set b_addr_line1 = (b_addr_data.get('address_line1') or '')|truncate(42, true, '...', 0) -%}
	{%- set b_addr_line2 = b_addr_data.get('address_line2') or '' -%}
	{%- set b_city = b_addr_data.get('city') or '' -%}
	
	{# Split Buyer Address Line 1 by the manual newline #}
	{%- set b_line1_parts = b_addr_line1.replace('\r\n', '\n').split('\n') -%}
	{%- set buyer_line_1 = b_line1_parts[0] if b_line1_parts|length > 0 else '' -%}
	{%- set buyer_line_2 = b_line1_parts[1] if b_line1_parts|length > 1 else '' -%}
	{%- set buyer_line_3 = b_city -%}

	{# Fetch and split Ship To Address #}
	{%- set s_addr_data = frappe.db.get_value('Address', doc.shipping_address_name, ['address_line1', 'address_line2', 'city'], as_dict=True) if doc.shipping_address_name else b_addr_data -%}
	{%- set s_addr_line1 = (s_addr_data.get('address_line1') or '')|truncate(42, true, '...', 0) -%}
	{%- set s_addr_line2 = s_addr_data.get('address_line2') or '' -%}
	{%- set s_city = s_addr_data.get('city') or '' -%}

	{%- set s_line1_parts = s_addr_line1.replace('\r\n', '\n').split('\n') -%}
	{%- set ship_line_1 = s_line1_parts[0] if s_line1_parts|length > 0 else '' -%}
	{%- set ship_line_2 = s_line1_parts[1] if s_line1_parts|length > 1 else '' -%}
    {%- set ship_line_3 = s_city -%}

<div class="sheet {% if is_last %}is-last{% endif %}">
    <div class="frame">

        <div class="topbar">

            <!-- ====== Company name and address, contact ========= -->
            <div>
                <div class="company-name">
                    <span><b>{{ doc.company }}</b></span>
                </div>
                <div class="address-contact">
                    <div class="address">
                        <span>{{ c_l1 }}</span>
                        <span>{{ c_l2 }}</span>
                    </div>
                </div>
            </div>

            <!-- ===================== TITLE ROW ===================== -->
            <div class="title">
                <div>
                    <p>&nbsp;</p>
                </div>
                <div>
                    <p class="dn-with-stock">DEBIT NOTE WITH STOCK</p>
                </div>
                <div>
                    <p class="original">Original</p>
                </div>
            </div>

            <!-- ===================== PARTY BOXES ===================== -->
            <div class="party">
                <div class="buyer-wrap">
                    <div class="buyer">
                        <div><b><span>M/s. <span>:</span></span> </b></div>
                        <div><span>&nbsp;</span></div>
                        <div><span>&nbsp;</span></div>
                        <div><span>&nbsp;</span></div>
                        <div><b><span>Place of Supply <span>:</span></span> </b></div>
                        <div><b><span>GSTIN No. <span>:</span></span> </b></div>
                    </div>
                    <div class="buyervalues">                            
                        {#<div><b><span>{{ b_name }}</span></b></div>#}
                        <div><b><span>{{ doc.supplier }}</span></b></div>
						<div><span>{{ b_addr_line1 or '&nbsp;'}}</span></div>
						<div><span>{{ b_addr_line2 or '&nbsp;' }}</span></div>
						<div><b><span>{{ buyer_line_3 or '&nbsp;'}}</span></b></div>
						<div><span>{{ b_place or '&nbsp;'}}</span></div>
					    <div><span>{{ b_gstin or '&nbsp;' }}</span></div>
                    </div>
                </div>
                <div class="ship-wrap">
                    <div class="dn-info">
                        <div class="ship">
                            <div><b><span>Debit Note No.<span>:</span></span> </b></div>
                            <div><b><span>Debit Note Dt.<span>:</span></span> </b></div>
                            <div><b><span>Original Bill No<span>:</span></span> </b></div>
                            <div><b><span>Original Bill Date<span>:</span></span> </b></div>
                        </div>
                        <div class="shipvalues">
                            <div><span>{{ doc.name }}</span></div>
                            <div><span>{{ doc.get_formatted('posting_date') }}</span></div>
                            <div><span>{{ doc.return_against or '&nbsp;' }}</span></div>
                            <div><span>{{ frappe.utils.format_date(orig_date_val) if orig_date_val else '&nbsp;' }}</span></div>
                        </div>
                    </div>
                    <div class="reason">
                        <div class="reason-for-label">
                            <div><b><span>Reason For<span>:</span></span> </b></div>
                        </div>
                        <div class="reason-for-values">
                            <div><span>{{ doc.return_reason or doc.get('reason_for_return') or '&nbsp;' }}</span></div>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- ===================== ITEMS TABLE ===================== -->
        <div class="items-wrap">
            <table class="items">
                <colgroup>
                    <col width="3%">
					<col width="27%">
					<col width="7%">
					<col width="6%">
					<col width="7%">
					<col width="7%">
					<col width="7%">
					<col width="8%">
					<col width="5%">
					<col width="7%">
					<col width="7%">
					<col width="9%">
                </colgroup>
                <thead>
                    <tr>
						<th rowspan="2">Sr.</th>
						<th rowspan="2">Product Name</th>
						<th rowspan="2">HSN/SAC Code</th>
						<th rowspan="2">Box</th>
						<th rowspan="2">Pcs</th>
						<th rowspan="2">Ltr</th>
						<th rowspan="2">Rate</th>
						<th rowspan="2">Taxable Amount</th>
						<th rowspan="2">GST %</th>
						<th colspan="2">Tax Amount</th>
						<th rowspan="2">Net Amount</th>
					</tr>
					<tr>
						<th>Central</th>
						<th>State/UT</th>
					</tr>
                </thead>
                <tbody>
					{%- for row in page_items -%}
                    	{%- set g.sr = g.sr + 1 -%}
                    	{%- set taxable = (row.net_amount or row.amount or 0)|float -%}
                    	
                    	{# FETCHING directly from the system's item row fields #}
                    	{%- set ct = (row.get('cgst_amount') or 0)|float -%}
                    	{%- set st = (row.get('sgst_amount') or 0)|float -%}
                    	{%- set item_gst_rate = (row.get('gst_rate') or row.get('gst_percentage') or 0)|float -%}
                    	
                    	{%- set net = taxable + ct + st -%}
                    	{%- set box = (row.fe_box or 0)|float -%}
                    	{%- set pcs = (row.pcs_qty or row.pcs or row.qty or 0)|float -%}
                    	{%- set ltr = (row.fe_ltr or row.ltr_qty or row.ltr or 0)|float -%}
                    	
                    	{%- set ps.box = ps.box + box -%}
                    	{%- set ps.pcs = ps.pcs + pcs -%}
                    	{%- set ps.ltr = ps.ltr + ltr -%}
                    	{%- set ps.taxable = ps.taxable + taxable -%}
                    	{%- set ps.cgst = ps.cgst + ct -%}
                    	{%- set ps.sgst = ps.sgst + st -%}
                    	{%- set ps.net = ps.net + net -%}
                    	<tr>
                    		<td>{{ g.sr }}</td>
                    		<td>{% set iname = row.item_name or row.item_code or row.description or '' %}{% if '-MRP-' in iname %}{{ iname.split('-MRP-')[0]|trim }}{% else %}{{ iname }}{% endif %}<div class="sub">MRP:-{% if row.get('mrp') %} {{ m2(row.mrp) }}{% endif %}</div></td>
                    		<td>{{ row.gst_hsn_code or row.hsn_sac or '' }}</td>
                    		<td>{{ "%.2f" | format(m2(box) | float | abs) }}</td>
                    		<td>{{ "%.2f" | format(m2(pcs) | float | abs) }}</td>
                    		<td>{{ m3(ltr) }}</td>
                    		<td>{{ m2(row.rate) | int | abs }}</td>
                    		<td>{{ m2(taxable) | int | abs }}</td>
                    		
                    		<td>18%</td>
                    		
                    		<td>{{ "%.2f" | format(m2(ct) | float | abs) }}</td>
                    		<td>{{ "%.2f" | format(m2(st) | float | abs) }}</td>
                    		<td>{{ "%.2f" | format(m2(net) | float | abs) }}</td>
                    	</tr>
                    {%- endfor -%}
					{%- if page_items|length < rows_per_page -%}
						<tr class="fill">
							<td></td><td></td><td></td><td></td><td></td><td></td>
							<td></td><td></td><td></td><td></td><td></td><td></td>
						</tr>
					{%- endif -%}
				</tbody>
                <tfoot>
                    <tr>
                        <td style="text-align: left; padding-left: 1mm !important;" colspan="2">GSTIN No.: {{ company_gstin }}</td>
                        <td style="border-left: none"></td>
                        <td></td>
                        <td></td>
                        <td>Total</td>
                        <td></td>
                        <td>{{ "%.2f" | format(m2(cum.taxable + ps.taxable) | float | abs) }}</td>
                        <td></td>
                        <td>{{ m2(cns.c) }}</td>
                        <td>{{ m2(cns.s) }}</td>
                        <td style="border-right: none !important;">{{ m2(cns.n) }}</td>
                    </tr>
                </tfoot>
            </table>
        </div>

        <!-- ===================== FOOTER ===================== -->
        <div class="footer">
            <!-- Bill Details -->
            <div class="bill-details">
                <div class="GST-ba-wrap">
                    <div class="GST-ba">
                        <div><b><span>Total GST <span>:</span></span> </b></div>
                        <div><b><span>Bill Amount <span>:</span></span> </b></div>
                    </div>
                    <div class="GST-ba-values">
                        <div><i><span>{{ total_gst_words }}</span></i></div>
                        <div><i><span>{{ rounded_amount_words }}</span></i></div>
                    </div>
                </div>
                <div class="ro-gt-wrap">
                    <div class="ro-info">
                        <div class="ro">
                            <div><b><span>Total GST<span>:</span></span> </b></div>
                            <div><b><span>Round Off<span>:</span></span> </b></div>
                        </div>
                        <div class="ro-values">
                            {#<div><span>{{ m2(total_gst) }}</span></div>#}
                            <div><span>{{ frappe.utils.fmt_money(total_gst | float) }}</span></div>
                            <div><span>{{ sgn(round_off) }}</span></div>
                        </div>
                    </div>
                    <div class="gt-info">
                        <div class="gt-label{% if not is_last %} cf{% endif %}">
                            <div><b><span>{% if is_last %}Grand Total<span>:</span>{% else %}C/F to Next Page<span>:</span>{% endif %} </span></b></div>
                        </div>
                        <div class="gt-values{% if not is_last %} cf{% endif %}">
                            {#<div><span>{% if is_last %}{{ "%.2f" | format(m2(rounded_total) | float | abs) }}{% else %}{{  mcm(cns.n) }}{% endif %}</span></div>#}
                            <div><span>{% if is_last %}{{ frappe.utils.fmt_money(rounded_total | float) }}{% else %}{{  mcm(cns.n) }}{% endif %}</span></div>
                        </div>
                    </div>
                </div>
            </div>
            <!-- Bank Details -->
            <div class="bank-details">
                <div class="bank-wrap">
                    <div class="bank">
                        <div><b><span>Bank Name <span>:</span></span> </b></div>
                        <div><b><span>Bank A/c. No. <span>:</span></span> </b></div>
                        <div><b><span>RTGS/IFSC Code <span>:</span></span> </b></div>
                    </div>
                    <div class="bankvalues">
                        <div><i><span>{{ doc.bank_name or 'IDFC BANK' }}</span></i></div>
                        <div><i><span>{{ doc.bank_account_no or doc.bank_account or ' 10119404064' }}</span></i></div>
                        <div><i><span>{{ doc.ifsc_code or ' IDFB0042267' }}</span></i></div>
                    </div>
                </div>
                <div class="note-wrap">
                    <div class="note">
                        <div><b><span>Note<span>:</span></span> </b></div>
                    </div>
                    <div class="notevalues">
                        <div><span></span></div>
                    </div>
                </div>
            </div>

            <!-- Terms and Conditions and Signatory -->
            <div class="tandcandsign">
                <div class="tandc">
                    <b>Terms &amp; Condition :</b>
                    {% if doc.terms %}
                    {{ doc.terms }}
                    {% else %}
                    <ol class="terms">
                        <li>Goods once sold will not be taken back.</li>
