{%- for t in doc.taxes or [] -%}
{%- set ah = (t.account_head or '')|lower -%}
{%- if 'refund' not in ah -%}
{%- if 'cgst' in ah -%}{%- set dtax.cgst = dtax.cgst + (t.tax_amount|float) -%}{%- if not dtax.c_rate -%}{%- set dtax.c_rate = (t.rate|float) -%}{%- endif -%}{%- endif -%}
{%- if 'sgst' in ah -%}{%- set dtax.sgst = dtax.sgst + (t.tax_amount|float) -%}{%- if not dtax.s_rate -%}{%- set dtax.s_rate = (t.rate|float) -%}{%- endif -%}{%- endif -%}
{%- if 'igst' in ah -%}{%- set dtax.igst = dtax.igst + (t.tax_amount|float) -%}{%- endif -%}
{%- endif -%}
{%- endfor -%}
